// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guess) public {
        address actor = address(0xABCD);
        vm.deal(actor, 2 ether);

        // Lock a guess equal to `guess` (any value the fuzzer chooses, including
        // ones that will never equal a blockhash).
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Move forward so settle is permitted: block.number > stored block.
        vm.roll(block.number + 2);

        uint256 balBefore = actor.balance;

        // Commit the blockhash of the settle block is essentially random;
        // we deliberately keep the fuzzed `guess` arbitrary so that with
        // overwhelming probability it does NOT equal the answer blockhash.
        vm.prank(actor);
        c.settle();

        uint256 balAfter = actor.balance;

        // General rule: settle must pay 2 ether ONLY when the revealed
        // blockhash equals the committed guess.  When the fuzzer supplies an
        // arbitrary guess (almost surely not the blockhash), C must pay
        // nothing, whereas M pays 2 ether whenever the answer is non-zero.
        assertTrue(balAfter == balBefore);
    }
}
